SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, s.hadm_id, s.admittime, s.dischtime, s.deathtime, s.admission_type, s.admit_provider_id, s.admission_location, s.discharge_location, s.insurance, s.language, s.marital_status, s.race, s.edregtime, s.edouttime, s.hospital_expire_flag, ph.pharmacy_id, ph.poe_id, ph.poe_seq, ph.order_provider_id, ph.order_status, ph.starttime, ph.endtime, ph.drug_type, ph.drug, ph.formulary_drug_cd, ph.gsn, ph.ndc, ph.prod_strength, ph.form_rx, ph.dose_val_rx, ph.dose_unit_rx, ph.form_val_disp, ph.form_unit_disp, ph.doses_per_24_hrs, ph.route, ph.infusion_type, ph.sliding_scale, ph.lockout_interval, ph.basal_rate, ph.one_hr_max, ph.dose_due, ph.dose_due_unit, ph.dose_given, ph.dose_given_unit, ph.will_remainder_of_dose_be_given, ph.product_amount_given, ph.product_unit, ph.product_code, ph.product_description, lag(ph.dose_given) OVER (PARTITION BY ph.poe_id ORDER BY ph.starttime) AS previous_dose_given, lead(ph.dose_given) OVER (PARTITION BY ph.poe_id ORDER BY ph.starttime) AS next_dose_given, (ph.dose_given - lag(ph.dose_given) OVER (PARTITION BY ph.poe_id ORDER BY ph.starttime))/NULLIF((s.dischtime - s.admittime), 0) AS net_dose_change, CASE WHEN ph.drug_type = 'Insulin' THEN 'Insulin' ELSE 'Oral' END AS drug_category, CASE WHEN ph.starttime BETWEEN 0 AND 48 THEN '0-48h' ELSE 'Final 72h' END AS time_window, COUNT(DISTINCT s.hadm_id) AS num_admissions, SUM(CASE WHEN ph.drug_type = 'Insulin' THEN 1 ELSE 0 END) AS insulin_admissions, SUM(CASE WHEN ph.drug_type = 'Oral' THEN 1 ELSE 0 END) AS oral_admissions, SUM(CASE WHEN ph.starttime BETWEEN 0 AND 48 THEN 1 ELSE 0 END) AS early_admissions, SUM(CASE WHEN ph.starttime BETWEEN 48 AND 72 THEN 1 ELSE 0 END) AS late_admissions FROM patients p JOIN admissions s ON p.subject_id = s.subject_id JOIN pharmacy ph ON s.hadm_id = ph.hadm_id WHERE p.subject_id = 100001 AND p.gender = 'M' AND p.anchor_age = 82 AND p.anchor_year = 2017 AND p.anchor_year_group = '87' AND s.admission_type = 'IM' AND s.discharge_location = 'ICU' AND s.insurance = 'Private' AND s.language = 'English' AND s.marital_status = 'M' AND s.race = 'White' AND s.edregtime <= '2017-01-01' AND s.edouttime >= '2017-12-31' AND (s.dischtime - s.admittime) <= 48 AND (s.dischtime - s.admittime) >= 72 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, s.hadm_id, s.admittime, s.dischtime, s.deathtime, s.admission_type, s.admit_provider_id, s.admission_location, s.discharge_location, s.insurance, s.language, s.marital_status, s.race, s.edregtime, s.edouttime, s.hospital_expire_flag, ph.pharmacy_id, ph.poe_id, ph.poe_seq, ph.order_provider_id, ph.order_status, ph.starttime, ph.endtime, ph.drug_type, ph.drug, ph.formulary_drug_cd, ph.gsn, ph.ndc, ph.prod_strength, ph.form_rx, ph.dose_val_rx, ph.dose_unit_rx, ph.form_val_disp, ph.form_unit_disp, ph.doses_per_24_hrs, ph.route, ph.infusion_type, ph.sliding_scale, ph.lockout_interval, ph.basal_rate, ph.one_hr_max, ph.dose_due, ph.dose_due_unit, ph.dose_given, ph.dose_given_unit, ph.will_remainder_of_dose_be_given, ph.product_amount_given, ph.product_unit, ph.product_code, ph.product_description, time_window;